if.script:
ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", existingOpen[0].sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

actions.script:
def _opId = ec.user.userAccount?.partyId
if (_opId) {
    ec.entity.find("zenith.erp.pos.PosSession")
        .condition("operatorPartyId", _opId).condition("statusId", "PsOpen").list().each { os ->
        def soldCount = ec.entity.find("zenith.erp.pos.PosTransaction")
            .condition("sessionId", os.sessionId).condition("statusId", "PtCompleted").count()
        if (soldCount == 0) {
            ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", os.sessionId).condition("statusId", "PtCreated").list().each { st ->
                ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
                ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
                ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
                try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
            }
            ec.service.sync().name("update#zenith.erp.pos.PosSession")
                .parameters([sessionId: os.sessionId, statusId:'PsClosed', closeDate: ec.user.nowTimestamp, closingCash: (os.openingCash ?: 0)]).call()
            ec.logger.info("Start-fresh: retired abandoned POS session " + os.sessionId + " (operator " + _opId + ")")
        }
    }
}

try {
    def warmProd = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _term?.organizationPartyId).limit(1).list()[0]
    if (warmProd) {
        def _wOrg = _term?.organizationPartyId
        def _wGeo = _term?.regionGeoId ?: 'IND_TN'
        ec.service.sync().name("zenith.pricing.PricingServices.calculate#Price")
            .parameters([productId:warmProd.productId, organizationPartyId:_wOrg, quantity:1, salesChannelEnumId:'ScPos']).call()
        ec.service.sync().name("zenith.tax.TaxServices.calculate#Tax")
            .parameters([organizationPartyId:_wOrg, originRegionGeoId:_wGeo, destinationRegionGeoId:_wGeo, isTaxInclusive:'N',
                         items:[[productId:warmProd.productId, productTaxCode:(warmProd.productTaxCode ?: ''), quantity:1, unitPrice:(warmProd.mrpAmount ?: 1), taxCategoryId:warmProd.taxCategoryId]]]).call()
    }
} catch (Throwable e) { ec.logger.warn("POS warmup skipped: " + e.message) }
ec.message.clearErrors()

def txns = ec.entity.find("zenith.erp.pos.PosTransaction")
    .condition("sessionId", sessionId)
    .condition("statusId", "PtCompleted").list()
def txnIds = txns*.transactionId

def cashReceived = 0 as BigDecimal
if (txnIds) {
    def payments = ec.entity.find("zenith.erp.pos.PosPayment")
        .condition("transactionId", "in", txnIds)
        .condition("paymentMethod", "Cash").list()
    payments.each { cashReceived += (it.amount ?: 0) as BigDecimal }
}

def changeGiven = 0 as BigDecimal
txns.each { changeGiven += (it.changeAmount ?: 0) as BigDecimal }

def expectedCash = (session.openingCash ?: 0) as BigDecimal + cashReceived - changeGiven
def cashDiff = (closingCash as BigDecimal) - expectedCash

ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

def fyStr = null
if (txn.organizationPartyId) {
    try {
        def fyResult = ec.service.sync().name("zenith.base.LocalizationServices.get#FinancialYearDates")
            .parameter("organizationPartyId", txn.organizationPartyId).call()
        fyStr = fyResult?.fyLabel
    } catch (Exception e) { /* fall through to date-based number */ }
}
if (!fyStr) {
    def now = ec.user.nowTimestamp
    fyStr = new java.text.SimpleDateFormat("yyyy-MM").format(now)
}
// Atomic per-(org, financial-year) bill counter: an O(1) row-locked increment instead of a
// growing full-table count scan, and race-safe (two registers can never mint the same number).
def org = txn?.organizationPartyId ?: '_NA_'
def seqKey = org + "_" + fyStr
def nextNum
def counter = ec.entity.find("zenith.erp.pos.PosBillSequence").condition("seqKey", seqKey).forUpdate(true).one()
if (counter != null) {
    nextNum = ((counter.lastNumber ?: 0) as int) + 1
    ec.service.sync().name("update#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
} else {
    // First bill for this org+FY: seed from the existing max so we never collide with or renumber prior bills.
    int mx = 0
    def prior = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", org)
        .condition("transactionNumber", "like", "POS/${fyStr}/%").selectField("transactionNumber").list()
    for (r in prior) {
        def m = (r.transactionNumber =~ /\/(\d+)$/)
        if (m.find()) { int n = m.group(1) as int; if (n > mx) mx = n }
    }
    nextNum = mx + 1
    try {
        ec.service.sync().name("create#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
    } catch (Exception e) {
        // concurrent first-bill for this key: another thread seeded it — re-read locked and increment
        def c2 = ec.entity.find("zenith.erp.pos.PosBillSequence").condition("seqKey", seqKey).forUpdate(true).one()
        nextNum = (((c2?.lastNumber ?: mx) as int)) + 1
        ec.service.sync().name("update#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
    }
}
def seqNum = String.format("%05d", nextNum)
transactionNumber = "POS/${fyStr}/${seqNum}"

import groovy.json.JsonOutput
def itemsList = items.collect { [productId: it.productId, productName: it.productName,
    quantity: it.quantity, unitPrice: it.unitPrice, discountPercent: it.discountPercent,
    lineTotal: it.lineTotal] }
itemsJson = JsonOutput.toJson(itemsList)

import groovy.json.JsonSlurper
def slurper = new JsonSlurper()
def synced = 0
transactions.each { txnStr ->
    def sale = null
    try { sale = slurper.parseText(txnStr as String) } catch (Exception e) { sale = null }
    if (sale == null) return

    // Idempotency: if this offline sale was already synced, skip (handles re-sync / double-fire)
    if (sale.offlineId) {
        def dup = ec.entity.find("zenith.erp.pos.PosPayment")
            .condition("referenceNumber", "OFFLINE:" + sale.offlineId).count()
        if (dup > 0) { synced += 1; return }
    }

    // SECURITY (org isolation): resolve the session ONLY within the caller's active org, so a
    // client-supplied terminalId/sessionId from another tenant can never attach a sale to that
    // tenant's books. No active org -> no session -> the sale is recorded OtPending, not injected.
    // (Also fixes the -openedDate orderBy: the field is openDate, so it was silently dropped.)
    def _activeOrg = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def sessionId = sale.sessionId
    def sess = sessionId ? ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).condition("organizationPartyId", _activeOrg).one() : null
    if (sess == null || sess.statusId != 'PsOpen') {
        def openList = ec.entity.find("zenith.erp.pos.PosSession")
            .condition("terminalId", sale.terminalId ?: terminalId)
            .condition("organizationPartyId", _activeOrg)
            .condition("statusId", "PsOpen").orderBy("-openDate").list()
        sess = openList ? openList[0] : null
    }

    def createdTxnId = null
    def status = 'OtPending'
    def errMsg = null
    if (sess != null) {
        try {
            def cr = ec.service.sync().name("zenith.pos.PosServices.create#PosTransaction")
                .parameters([sessionId: sess.sessionId, transactionType: 'Sale']).call()
            createdTxnId = cr.transactionId
            (sale.items ?: []).each { it ->
                ec.service.sync().name("zenith.pos.PosServices.add#PosTransactionItem")
                    .parameters([transactionId: createdTxnId, productId: it.productId,
                                 quantity: (it.qty ?: 1) as BigDecimal,
                                 unitPrice: (it.price ?: 0) as BigDecimal]).call()
            }
            // Pay the recomputed payable so completion succeeds even if tax shifted the total
            def txn = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", createdTxnId).one()
            def payable = (txn?.payableAmount ?: sale.total ?: 0) as BigDecimal
            ec.service.sync().name("zenith.pos.PosServices.process#PosPayment")
                .parameters([transactionId: createdTxnId,
                             paymentMethod: (sale.paymentMethod ?: 'Cash'),
                             amount: payable,
                             referenceNumber: ('OFFLINE:' + (sale.offlineId ?: ''))]).call()
            ec.service.sync().name("zenith.pos.PosServices.complete#PosTransaction")
                .parameters([transactionId: createdTxnId]).call()
            status = 'OtSynced'
            synced += 1
        } catch (Exception e) {
            status = 'OtFailed'
            errMsg = e.message
            ec.message.clearErrors()
        }
    }

    ec.service.sync().name("create#zenith.erp.pos.PosOfflineTransaction")
        .parameters([terminalId: (sale.terminalId ?: terminalId),
                     offlineTimestamp: ec.user.nowTimestamp,
                     syncedTimestamp: ec.user.nowTimestamp,
                     transactionDataJson: (txnStr as String),
                     itemCount: (sale.items ? sale.items.size() : 0),
                     grandTotal: (sale.total ?: 0) as BigDecimal,
                     paymentMethod: (sale.paymentMethod ?: ''),
                     statusId: status,
                     syncError: errMsg,
                     createdTransactionId: createdTxnId]).call()
}
syncedCount = synced

ec.user.loginAnonymousIfNoUser()
def cutoff = new java.sql.Timestamp(ec.user.nowTimestamp.time - (olderThanHours ?: 24) * 3600000L)
voidedCount = 0
ec.entity.find("zenith.erp.pos.PosTransaction").condition("statusId", "PtCreated").list().each { st ->
    if (st.transactionNumber) return                 // numbered = issued; never touch (belt+suspenders — PtCreated should never have one)
    if (!st.sessionId) return                        // unknown provenance — leave alone
    def sess = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", st.sessionId).one()
    if (!sess || sess.statusId != 'PsClosed') return // open/live session — a cashier may be mid-sale; NEVER touch
    if (sess.closeDate == null || sess.closeDate.after(cutoff)) return  // grace period after close
    def payCount = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).count()
    if (payCount > 0 || ((st.paidAmount ?: 0) as BigDecimal) > 0) {
        ec.logger.warn("void#OrphanedPosCarts: SKIPPING PtCreated cart " + st.transactionId + " on closed session " + st.sessionId + " — it has recorded payments; needs manual review")
        return
    }
    st.statusId = 'PtVoided'
    st.update()
    voidedCount++
}
if (voidedCount) ec.logger.info("void#OrphanedPosCarts: voided " + voidedCount + " orphaned PtCreated cart(s) on sessions closed > " + (olderThanHours ?: 24) + "h")
